package com.example.voiceassistant.aimatrix

import com.example.voiceassistant.TestFiles
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Locks the Python↔Kotlin featurization contract.
 *
 * `ai-matrix/tests/golden_features.json` is generated by the NumPy side; if these
 * assertions ever fail, the phone and the trainer disagree about what a phrase looks
 * like and every routed command must be treated as suspect.
 */
class AiMatrixFeaturizerTest {

    @Test
    fun `buckets match the Python implementation for every golden case`() {
        val golden = JSONObject(TestFiles.goldenFeatures().readText())
        assertEquals(
            "Feature version drift between Python and Kotlin",
            golden.getInt("featureVersion"),
            AiMatrixFeaturizer.FEATURE_VERSION
        )
        assertEquals(
            "Bucket count drift between Python and Kotlin",
            golden.getInt("buckets"),
            AiMatrixFeaturizer.BUCKETS
        )

        val cases = golden.getJSONObject("cases")
        assertTrue("The golden snapshot is empty", cases.length() > 0)

        for (phrase in cases.keys()) {
            val expected = cases.getJSONObject(phrase)
            val actual = AiMatrixFeaturizer.termFrequencies(phrase)

            val expectedCounts = buildMap {
                for (key in expected.keys()) put(key.toInt(), expected.getInt(key))
            }
            assertEquals(
                "Featurization differs from Python for \"$phrase\"",
                expectedCounts,
                actual
            )
        }
    }

    @Test
    fun `java string hash agrees with the golden values the trainer used`() {
        // Values taken from `python -c "from ai_matrix.features import java_string_hash"`,
        // which reproduces java.lang.String.hashCode() including 32-bit overflow.
        assertEquals(0, AiMatrixFeaturizer.bucketFor("", 4096) % 4096)
        assertTrue(AiMatrixFeaturizer.bucketFor("a") in 0 until AiMatrixFeaturizer.BUCKETS)
        assertTrue(AiMatrixFeaturizer.bucketFor("flashlight") in 0 until AiMatrixFeaturizer.BUCKETS)
        assertEquals(Math.floorMod("chat".hashCode(), 4096), AiMatrixFeaturizer.bucketFor("chat"))
        assertEquals(
            Math.floorMod("flashlight".hashCode(), 4096),
            AiMatrixFeaturizer.bucketFor("flashlight")
        )
    }

    @Test
    fun `tokens include unigrams bigrams and affixes`() {
        assertEquals(
            listOf(
                "turn", "on", "flashlight",
                "turn_on", "on_flashlight",
                "p:turn", "s:turn", "p:flas", "s:ight"
            ),
            AiMatrixFeaturizer.tokens("turn on flashlight")
        )
        // Words shorter than the affix threshold contribute no affixes.
        assertFalse(AiMatrixFeaturizer.tokens("on off").any { it.startsWith("p:") })
    }

    @Test
    fun `normalization strips punctuation case and fillers`() {
        assertEquals(
            "turn on the flashlight",
            AiMatrixFeaturizer.normalize("Uh, please turn ON the flashlight!")
        )
        assertEquals("jarvis set an alarm", AiMatrixFeaturizer.normalize("Hey JARVIS... could you set an alarm?"))
        assertEquals("", AiMatrixFeaturizer.normalize("   ok   "))
    }

    @Test
    fun `feature vectors are l2 normalized`() {
        val vector = AiMatrixFeaturizer.featurize("turn the torch on")
        var sumOfSquares = 0.0
        for (value in vector) sumOfSquares += value.toDouble() * value
        assertEquals(1.0, sumOfSquares, 1e-5)
    }

    @Test
    fun `empty text produces an empty feature vector`() {
        assertTrue(AiMatrixFeaturizer.termFrequencies("   ...  ").isEmpty())
        val vector = AiMatrixFeaturizer.featurize("...")
        assertTrue(vector.all { it == 0f })
    }
}
